import{_ as s,o as e,c as i,a2 as n}from"./chunks/framework.DZhUhjDB.js";const h=JSON.parse('{"title":"05 — Criptografía básica","description":"","frontmatter":{"title":"05 — Criptografía básica"},"headers":[],"relativePath":"modules/fundamentos/05-criptografia-basica.md","filePath":"modules/fundamentos/05-criptografia-basica.md","lastUpdated":1787330151000}'),t={name:"modules/fundamentos/05-criptografia-basica.md"};function r(o,a,l,d,c,p){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="_05-—-criptografia-basica" tabindex="-1">05 — Criptografía básica <a class="header-anchor" href="#_05-—-criptografia-basica" aria-label="Permalink to &quot;05 — Criptografía básica&quot;">​</a></h1><blockquote><p>🎯 <strong>Objetivo:</strong> entender los conceptos suficientes para no meter la pata. No vas a ser criptoanalista hoy, pero sí vas a saber qué algoritmo usar, cuándo y por qué.</p></blockquote><h2 id="_1-las-3-cosas-que-la-criptografia-protege" tabindex="-1">1. Las 3 cosas que la criptografía protege <a class="header-anchor" href="#_1-las-3-cosas-que-la-criptografia-protege" aria-label="Permalink to &quot;1. Las 3 cosas que la criptografía protege&quot;">​</a></h2><ul><li><strong>Confidencialidad</strong> — nadie más lee</li><li><strong>Integridad</strong> — nadie alteró sin permiso</li><li><strong>Autenticidad</strong> — séquién lo envió y que no fue alterado</li></ul><h2 id="_2-hash-—-la-huella-digital-de-un-dato" tabindex="-1">2. Hash — la huella digital de un dato <a class="header-anchor" href="#_2-hash-—-la-huella-digital-de-un-dato" aria-label="Permalink to &quot;2. Hash — la huella digital de un dato&quot;">​</a></h2><p>Un <strong>hash</strong> toma cualquier cantidad de datos y devuelve una cadena fija de tamaño.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;hola&quot;      → 4d...uo  (SHA-256)</span></span>
<span class="line"><span>&quot;hola.&quot;     → d8...xq  (distinto aunque cambies 1 carácter)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>Propiedades:</strong></p><ul><li>Determinista: misma entrada → mismo hash</li><li>Rápido de calcular</li><li>Irreversible: del hash no recuperas la entrada</li><li>Resistente a colisiones (casi imposible encontrar 2 entradas con mismo hash)</li></ul><p><strong>Algoritmos comunes:</strong></p><table tabindex="0"><thead><tr><th>Algoritmo</th><th>Tamaño</th><th>Estado</th></tr></thead><tbody><tr><td>MD5</td><td>128 bits</td><td>❌ Roto. Solo para legacy.</td></tr><tr><td>SHA-1</td><td>160 bits</td><td>❌ Roto. No uses.</td></tr><tr><td>SHA-256</td><td>256 bits</td><td>✅ Estándar actual.</td></tr><tr><td>SHA-3</td><td>256+ bits</td><td>✅ Más nuevo, alternativas.</td></tr><tr><td>BLAKE2</td><td>variable</td><td>✅ Muy rápido.</td></tr></tbody></table><p><strong>¿Para qué se usa un hash?</strong></p><ul><li>Guardar contraseñas: <code>hash(sal + password)</code> (no se guarda el password en claro)</li><li>Verificar integridad de archivos (un checksum descargado)</li><li>Firmas digitales (firmas sobre el hash, no el documento entero)</li><li>Blockchain / Bitcoin</li></ul><blockquote><p>⚠️ <strong>Error común</strong>: usar SHA-256 directamente sobre la contraseña. Correcto es usar un algoritmo lento y con sal: <strong>bcrypt, scrypt, Argon2</strong> (ver <code>01-CIBERSEGURIDAD/08-criptografia/</code>).</p></blockquote><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Calcular hash de un archivo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> archivo.txt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Get-FileHash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> archivo.txt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Windows PowerShell</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="_3-cifrado-simetrico-—-misma-clave-para-cifrar-y-descifrar" tabindex="-1">3. Cifrado simétrico — misma clave para cifrar y descifrar <a class="header-anchor" href="#_3-cifrado-simetrico-—-misma-clave-para-cifrar-y-descifrar" aria-label="Permalink to &quot;3. Cifrado simétrico — misma clave para cifrar y descifrar&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   ┌──── mensaje ────┐</span></span>
<span class="line"><span>        clave K</span></span>
<span class="line"><span>   └──── mismo K ────┘</span></span>
<span class="line"><span>   cifrado         descifrado</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>Algoritmos recomendados:</strong></p><ul><li><strong>AES-256-GCM</strong> — estándar de facto</li><li><strong>ChaCha20-Poly1305</strong> — alternativa moderna, móvil-friendly</li></ul><p><strong>Problema:</strong> ¿cómo compartes la clave sin que la intercepten?</p><h2 id="_4-cifrado-asimetrico-—-un-par-de-claves-publica-privada" tabindex="-1">4. Cifrado asimétrico — un par de claves (pública + privada) <a class="header-anchor" href="#_4-cifrado-asimetrico-—-un-par-de-claves-publica-privada" aria-label="Permalink to &quot;4. Cifrado asimétrico — un par de claves (pública + privada)&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Clave pública (cualquiera la ve)</span></span>
<span class="line"><span>            ↓ cifra</span></span>
<span class="line"><span>        mensaje cifrado</span></span>
<span class="line"><span>            ↓ descifra con clave privada</span></span>
<span class="line"><span>        mensaje original</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Clave privada (solo tú)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>Algoritmos:</strong></p><ul><li><strong>RSA</strong> — clásico, usa factores primos grandes</li><li><strong>ECC / Curve25519</strong> — más moderno, menor tamaño de clave</li><li><strong>Ed25519</strong> — para firmas digitales</li></ul><p><strong>¿Para qué sirve?</strong></p><ul><li>Cifrar: cualquiera cifra con tu pública, solo tú descifras con tu privada</li><li>Firmar: tú firmas con tu privada, cualquiera verifica con tu pública</li><li>HTTPS usa esto para acordar una clave simétrica y luego todo va cifrado con AES</li></ul><h2 id="_5-firmas-digitales-—-autenticidad" tabindex="-1">5. Firmas digitales — autenticidad <a class="header-anchor" href="#_5-firmas-digitales-—-autenticidad" aria-label="Permalink to &quot;5. Firmas digitales — autenticidad&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Hash del documento</span></span>
<span class="line"><span>2. Cifras el hash con tu clave privada → firma</span></span>
<span class="line"><span>3. Adjuntas firma al documento</span></span>
<span class="line"><span>4. Receptor: descifra la firma con tu pública → compara con hash del documento</span></span>
<span class="line"><span>   → si coinciden: íntegro y auténtico</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="_6-certificados-y-pki" tabindex="-1">6. Certificados y PKI <a class="header-anchor" href="#_6-certificados-y-pki" aria-label="Permalink to &quot;6. Certificados y PKI&quot;">​</a></h2><p>Un <strong>certificado digital</strong> (<code>X.509</code>) ata una identidad (ej: dominio <code>google.com</code>) a una clave pública. Lo firma una <strong>CA (Certificate Authority)</strong> de confianza (Let&#39;s Encrypt, DigiCert, etc.).</p><p><strong>Cadena de confianza:</strong> tu certificado → CA intermedia → CA raíz (que tu navegador ya confía).</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ver el certificado de una web</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com:443</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -showcerts</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Extraer info</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com:443</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x509</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -subject</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -issuer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dates</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="_7-https-—-que-pasa-realmente" tabindex="-1">7. HTTPS — qué pasa realmente <a class="header-anchor" href="#_7-https-—-que-pasa-realmente" aria-label="Permalink to &quot;7. HTTPS — qué pasa realmente&quot;">​</a></h2><ol><li><strong>Tu navegador</strong> → &quot;Hola, quiero HTTPS&quot;</li><li><strong>Servidor</strong> → &quot;Aquí mi certificado (clave pública)&quot;</li><li><strong>Tu navegador</strong> → verifica la cadena</li><li>Ambos acuerdan un <strong>algoritmo</strong> y generan una <strong>clave simétrica</strong> (TLS handshake)</li><li>A partir de ahí, todo va cifrado con AES (clave simétrica)</li></ol><p>La asimétrica solo se usa al principio para acordar la clave simétrica. Luego va rápido porque AES es más eficiente.</p><h2 id="_8-errores-comunes-que-vas-a-ver-y-debes-reconocer" tabindex="-1">8. Errores comunes que vas a ver (y debes reconocer) <a class="header-anchor" href="#_8-errores-comunes-que-vas-a-ver-y-debes-reconocer" aria-label="Permalink to &quot;8. Errores comunes que vas a ver (y debes reconocer)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Significado</th></tr></thead><tbody><tr><td><code>certificate expired</code></td><td>El servidor忘记 renovar. O un atacante.</td></tr><tr><td><code>self-signed certificate</code></td><td>Servidor firmó su propio cert. Confiar = riesgo.</td></tr><tr><td><code>hostname mismatch</code></td><td>El cert es para otro dominio. Sospechoso.</td></tr><tr><td><code>untrusted CA</code></td><td>CA no está en la lista de CAs confiables.</td></tr><tr><td><code>mixed content</code></td><td>Página HTTPS carga recursos HTTP. Mal.</td></tr></tbody></table><h2 id="_9-conceptos-adicionales-que-vas-a-oir" tabindex="-1">9. Conceptos adicionales que vas a oír <a class="header-anchor" href="#_9-conceptos-adicionales-que-vas-a-oir" aria-label="Permalink to &quot;9. Conceptos adicionales que vas a oír&quot;">​</a></h2><ul><li><strong>Sal (salt)</strong> — string aleatorio añadido al password antes de hashear. Evita rainbow tables.</li><li><strong>PBKDF2 / bcrypt / scrypt / Argon2</strong> — funciones de hash lentas a propósito para passwords.</li><li><strong>Nonce</strong> — número único por mensaje que evita replay attacks.</li><li><strong>KDF</strong> — Key Derivation Function: convierte una contraseña débil en clave criptográfica fuerte.</li><li><strong>HSM</strong> — Hardware Security Module: hardware dedicado a claves criptográficas.</li><li><strong>Quantum-safe crypto</strong> — Algoritmos resistentes a computación cuántica (CRYSTALS-Kyber, etc.).</li></ul><h2 id="📌-donde-profundizar" tabindex="-1">📌 Dónde profundizar <a class="header-anchor" href="#📌-donde-profundizar" aria-label="Permalink to &quot;📌 Dónde profundizar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Carpeta</th></tr></thead><tbody><tr><td>Cripto aplicada</td><td><a href="./../01-CIBERSEGURIDAD/08-criptografia/"><code>01-CIBERSEGURIDAD/08-criptografia/</code></a></td></tr><tr><td>Seguridad de cadena de suministro</td><td><a href="./../01-CIBERSEGURIDAD/seguridad-cadena-suministro/"><code>01-CIBERSEGURIDAD/seguridad-cadena-suministro/</code></a></td></tr><tr><td>Forense y descifrado</td><td><a href="./../01-CIBERSEGURIDAD/forense-digital/"><code>01-CIBERSEGURIDAD/forense-digital/</code></a></td></tr><tr><td>Cryptographer role</td><td><a href="./../01-CIBERSEGURIDAD/cryptographer/"><code>01-CIBERSEGURIDAD/cryptographer/</code></a></td></tr></tbody></table><h2 id="✏️-ejercicios" tabindex="-1">✏️ Ejercicios <a class="header-anchor" href="#✏️-ejercicios" aria-label="Permalink to &quot;✏️ Ejercicios&quot;">​</a></h2><ol><li><strong>Hash:</strong> hashea dos archivos iguales y compara. Cambia un byte y vuelve a hashear. Mira cómo cambia completamente el hash.</li><li><strong>Cifrado simétrico:</strong> cifra un mensaje tuyo con <code>openssl enc -aes-256-gcm -salt -in msg.txt -out msg.enc</code>. Descífralo.</li><li><strong>Genera claves SSH:</strong> <code>ssh-keygen -t ed25519</code>. Mira tu pública (<code>cat ~/.ssh/id_ed25519.pub</code>).</li><li><strong>Verifica un cert:</strong> visita <code>https://github.com</code>, click en el candado → mira &quot;Connection is secure&quot; → &quot;Certificate is valid&quot;.</li></ol><blockquote><p>⏭️ <strong>Siguiente:</strong> <a href="./06-vulnerabilidades"><code>06-vulnerabilidades.md</code></a> — qué es una vulnerabilidad y cómo se clasifica.</p></blockquote>`,44)])])}const g=s(t,[["render",r]]);export{h as __pageData,g as default};
